import os, base64
res_dir = r"c:\Users\ADMIN\Documents\Lurnexa\Lurnexa_Mobile_Desktop_Apps\mobile-app\android\app\src\main\res"

files_data = {
    "drawable/splash.png": "",
    "mipmap-hdpi/ic_launcher.png": "",
    "mipmap-hdpi/ic_launcher_foreground.png": "",
    "mipmap-hdpi/ic_launcher_round.png": "",
    "mipmap-mdpi/ic_launcher.png": "",
    "mipmap-mdpi/ic_launcher_foreground.png": "",
    "mipmap-mdpi/ic_launcher_round.png": "",
    "mipmap-xhdpi/ic_launcher.png": "",
    "mipmap-xhdpi/ic_launcher_foreground.png": "",
    "mipmap-xhdpi/ic_launcher_round.png": "",
    "mipmap-xxhdpi/ic_launcher.png": "",
    "mipmap-xxhdpi/ic_launcher_foreground.png": "",
    "mipmap-xxhdpi/ic_launcher_round.png": "",
    "mipmap-xxxhdpi/ic_launcher.png": "",
    "mipmap-xxxhdpi/ic_launcher_foreground.png": "",
    "mipmap-xxxhdpi/ic_launcher_round.png": "",
}

for rel_path, b64_str in files_data.items():
    dest_path = os.path.join(res_dir, rel_path.replace("/", os.sep))
    os.makedirs(os.path.dirname(dest_path), exist_ok=True)
    if os.path.exists(dest_path):
        try:
            os.remove(dest_path)
        except Exception:
            pass
    with open(dest_path, "wb") as fp:
        fp.write(base64.b64decode(b64_str))
    print(f"Decoded {rel_path}")